item = _items[0]['json']
body = item['body'] if isinstance(item.get('body'), dict) else {}
headers = item['headers'] if isinstance(item.get('headers'), dict) else {}

def field(key):
    value = body.get(key)
    return value.strip() if isinstance(value, str) else ''

ticket_id, email, message, tier = (field(key) for key in ('ticket_id', 'customer_email', 'message', 'tier'))

errors = []
if not re.fullmatch(r'[A-Za-z0-9_-]{1,100}', ticket_id):
    errors.append('ticket_id must be 1-100 letters, digits, _ or -')
if not re.fullmatch(r'[^\s@]+@[^\s@]+\.[^\s@]+', email):
    errors.append('customer_email must be a valid email')
if not message or len(message) > 20000:
    errors.append('message must be 1-20000 characters')
if not tier or len(tier) > 80:
    errors.append('tier must be 1-80 characters')
if errors:
    return [{'json': {'status': 'invalid_request', 'ticket_id': ticket_id or None, 'errors': errors, 'http_status': 400}}]

output = {
    'status': 'validated',
    'valid': True,
    'ticket_id': ticket_id,
    'tier': tier,
    'customer_email': '[REDACTED_EMAIL]',
    'sanitized_message': sanitize_pii(message),
    'http_status': 200,
}
# Fault injection for demos and tests: X-Mock-Model-Status: 429|503|200 makes Classify Ticket call
# the local mock model (workflows/mock-model.json) instead of DeepSeek and get that status back.
mock_status = str(headers.get('x-mock-model-status', '')).strip()
if re.fullmatch(r'[1-5]\d\d', mock_status):
    output['mock_model_status'] = int(mock_status)
return [{'json': output}]

