// Idempotency key: ticket_id. State lives in n8n's own database (workflow static data),
// so the demo needs no external store. Single-instance only: two workers could both pass
// this check at once - production should claim the id in a DB with a unique constraint.
const DEDUPE_TTL_MS = 7 * 24 * 60 * 60 * 1000;
const ticket = $input.first().json;
const state = $getWorkflowStaticData('global');
const now = Date.now();
const persistedSeen = state.seen_tickets;
const seen = Object.assign(
  Object.create(null),
  persistedSeen && typeof persistedSeen === 'object' ? persistedSeen : {},
);
for (const [id, seenAt] of Object.entries(seen)) {
  if (now - seenAt > DEDUPE_TTL_MS) delete seen[id];
}
state.seen_tickets = seen;

if (Object.prototype.hasOwnProperty.call(seen, ticket.ticket_id)) {
  return [{ json: {
    status: 'duplicate',
    ticket_id: ticket.ticket_id,
    first_seen_at: new Date(seen[ticket.ticket_id]).toISOString(),
    http_status: 200,
  } }];
}

seen[ticket.ticket_id] = now;
return [{ json: ticket }];

const response = $input.first().json;
const ticket = $('Validate and Mask PII').first().json;
const attempt = $runIndex + 1; // this node runs once per classification attempt

function failure(status, reason) {
  return [{ json: { ...ticket, classification_status: status, reason, attempt } }];
}

if (response.error) {
  const code = Number(response.error.statusCode || response.error.status
    || response.error.httpCode || response.statusCode);
  const retryable = !code || code === 429 || code >= 500;
  return failure(retryable ? 'retryable' : 'needs_review', 'model_unavailable');
}
const code = Number(response.statusCode);
if (code === 429 || code >= 500) {
  return failure('retryable', 'model_unavailable');
}
if (code && (code < 200 || code >= 300)) {
  return failure('needs_review', 'model_unavailable');
}

let body = response.body || response;
if (typeof body === 'string') {
  try {
    body = JSON.parse(body);
  } catch {
    return failure('needs_review', 'invalid_classification');
  }
}
const choice = body.choices?.[0];
if (choice?.finish_reason !== 'stop' || typeof choice.message?.content !== 'string') {
  return failure('needs_review', 'invalid_classification');
}

let classification;
try {
  classification = JSON.parse(choice.message.content);
} catch {
  return failure('needs_review', 'invalid_classification');
}

const allowed = ['Low', 'Medium', 'High', 'Critical'];
if (!classification || !allowed.includes(classification.severity)
  || typeof classification.summary !== 'string' || !classification.summary.trim()) {
  return failure('needs_review', 'invalid_classification');
}

return [{ json: {
  ...ticket,
  classification_status: 'classified',
  severity: classification.severity,
  summary: classification.summary.trim().slice(0, 160),
  classification_source: 'deepseek',
  attempt,
} }];

const ticket = $input.first().json;
const state = $getWorkflowStaticData('global');
const seen = state.seen_tickets;
if (seen && typeof seen === 'object') delete seen[ticket.ticket_id];
return [{ json: {
  status: 'needs_review',
  ticket_id: ticket.ticket_id,
  reason: ticket.reason || 'model_unavailable',
  http_status: 202,
} }];

const ticket = $input.first().json;
return [{ json: {
  ...ticket,
  asana_task: {
    name: `[${ticket.severity}] ${ticket.ticket_id}: ${ticket.summary}`,
    notes: ticket.sanitized_message,
    simulated: true,
  },
} }];

const ticket = $input.first().json;
return [{ json: {
  ...ticket,
  slack_alert: {
    text: `Critical Enterprise ticket ${ticket.ticket_id}: ${ticket.summary}`,
    simulated: true,
  },
} }];

const ticket = $input.first().json;
return [{ json: {
  status: 'accepted_mock',
  route: 'asana_slack',
  ticket_id: ticket.ticket_id,
  severity: ticket.severity,
  summary: ticket.summary,
  asana_task: ticket.asana_task,
  slack_alert: ticket.slack_alert,
  http_status: 202,
} }];

const ticket = $input.first().json;
return [{ json: {
  ...ticket,
  hubspot_ticket: {
    subject: `[${ticket.severity}] ${ticket.ticket_id}: ${ticket.summary}`,
    content: ticket.sanitized_message,
    simulated: true,
  },
} }];

const ticket = $input.first().json;
return [{ json: {
  status: 'accepted_mock',
  route: 'hubspot',
  ticket_id: ticket.ticket_id,
  severity: ticket.severity,
  summary: ticket.summary,
  hubspot_ticket: ticket.hubspot_ticket,
  http_status: 202,
} }];
